import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";
import private_api from "../../server/private_api";

const ProfessorAvaliacoes = () => {
  const { professorId } = useParams();
  const [avaliacoes, setAvaliacoes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedAvaliacao, setSelectedAvaliacao] = useState(null);
  const [selectedSubmissao, setSelectedSubmissao] = useState(null);

  useEffect(() => {
    const fetchAvaliacoes = async () => {
      try {
        const response = await private_api.get(
          `/professores/${professorId}/avaliacoes`
        );
        setAvaliacoes(response.data);
        setLoading(false);
      } catch (error) {
        console.error("Erro ao carregar avaliações:", error);
        setLoading(false);
      }
    };

    fetchAvaliacoes();
  }, [professorId]);

  const handleViewSubmissao = (submissao) => {
    setSelectedSubmissao(submissao);
  };

  const handleCloseModal = () => {
    setSelectedSubmissao(null);
  };

  if (loading) {
    return (
      <div
        className="d-flex justify-content-center align-items-center"
        style={{ height: "100vh" }}
      >
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  return (
    <div className="container-fluid py-4">
      <h2 className="mb-4">Avaliações e Submissões dos Alunos</h2>

      <div className="row">
        <div className="col-md-12">
          {avaliacoes.length === 0 ? (
            <div className="alert alert-info">
              Nenhuma avaliação encontrada.
            </div>
          ) : (
            <div className="accordion" id="avaliacoesAccordion">
              {avaliacoes.map((avaliacao, index) => (
                <div className="accordion-item" key={avaliacao.id}>
                  <h2 className="accordion-header">
                    <button
                      className={`accordion-button ${
                        index === 0 ? "" : "collapsed"
                      }`}
                      type="button"
                      data-bs-toggle="collapse"
                      data-bs-target={`#collapse${index}`}
                      aria-expanded={index === 0 ? "true" : "false"}
                      onClick={() => setSelectedAvaliacao(avaliacao)}
                    >
                      {avaliacao.titulo} - {avaliacao.curso?.nome}
                      <span className="badge bg-secondary ms-2">
                        {avaliacao.submissoes.length} submissões
                      </span>
                    </button>
                  </h2>
                  <div
                    id={`collapse${index}`}
                    className={`accordion-collapse collapse ${
                      index === 0 ? "show" : ""
                    }`}
                    data-bs-parent="#avaliacoesAccordion"
                  >
                    <div className="accordion-body">
                      <p>
                        <strong>Descrição:</strong> {avaliacao.descricao}
                      </p>
                      <p>
                        <strong>Período:</strong>{" "}
                        {new Date(avaliacao.dataInicio).toLocaleString()} até{" "}
                        {new Date(avaliacao.dataFim).toLocaleString()}
                      </p>

                      <h5 className="mt-4">Submissões dos Alunos</h5>
                      {avaliacao.submissoes.length === 0 ? (
                        <div className="alert alert-warning">
                          Nenhuma submissão encontrada para esta avaliação.
                        </div>
                      ) : (
                        <div className="table-responsive">
                          <table className="table table-striped table-hover">
                            <thead>
                              <tr>
                                <th>Aluno</th>
                                <th>Pontuação</th>
                                <th>Tempo</th>
                                <th>Data de Submissão</th>
                                <th>Ações</th>
                              </tr>
                            </thead>
                            <tbody>
                              {avaliacao.submissoes.map((submissao) => (
                                <tr key={submissao.id}>
                                  <td>{submissao.nomeAluno}</td>
                                  <td>
                                    {submissao.pontuacao}/
                                    {avaliacao.pontuacaoMaxima}
                                    <div
                                      className="progress mt-1"
                                      style={{ height: "5px" }}
                                    >
                                      <div
                                        className="progress-bar bg-success"
                                        role="progressbar"
                                        style={{
                                          width: `${
                                            (submissao.pontuacao /
                                              avaliacao.pontuacaoMaxima) *
                                            100
                                          }%`,
                                        }}
                                        aria-valuenow={submissao.pontuacao}
                                        aria-valuemin="0"
                                        aria-valuemax={
                                          avaliacao.pontuacaoMaxima
                                        }
                                      ></div>
                                    </div>
                                  </td>
                                  <td>{submissao.tempo}</td>
                                  <td>{submissao.entregue}</td>
                                  <td>
                                    <button
                                      className="btn btn-sm btn-primary"
                                      onClick={() =>
                                        handleViewSubmissao(submissao)
                                      }
                                    >
                                      Ver Respostas
                                    </button>
                                  </td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Modal para visualizar submissão */}
      {selectedSubmissao && (
        <div
          className="modal fade show"
          style={{ display: "block", backgroundColor: "rgba(0,0,0,0.5)" }}
        >
          <div className="modal-dialog modal-lg">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">
                  Respostas de {selectedSubmissao.nomeAluno}
                </h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={handleCloseModal}
                ></button>
              </div>
              <div className="modal-body">
                <div className="mb-3">
                  <h6>Detalhes da Submissão</h6>
                  <p>
                    <strong>Pontuação:</strong> {selectedSubmissao.pontuacao}/
                    {selectedAvaliacao?.pontuacaoMaxima}
                  </p>
                  <p>
                    <strong>Tempo gasto:</strong> {selectedSubmissao.tempo}
                  </p>
                  <p>
                    <strong>Data de submissão:</strong>{" "}
                    {selectedSubmissao.entregue}
                  </p>
                </div>

                <h6 className="mt-4">Respostas</h6>
                {selectedAvaliacao?.perguntas?.map((pergunta, index) => {
                  const respostaAluno =
                    selectedSubmissao.respostas?.[index]?.resposta ||
                    "Nenhuma resposta fornecida";
                  const respostaCorreta = pergunta.respostaCorreta;
                  const estaCorreta = respostaAluno === respostaCorreta;

                  return (
                    <div key={index} className="card mb-3">
                      <div
                        className={`card-header ${
                          estaCorreta
                            ? "bg-success text-white"
                            : "bg-danger text-white"
                        }`}
                      >
                        Pergunta {index + 1} - {pergunta.pontuacao || 1}{" "}
                        ponto(s)
                      </div>
                      <div className="card-body">
                        <h5 className="card-title">{pergunta.pergunta}</h5>
                        <div className="mb-3">
                          <p>
                            <strong>Resposta do aluno:</strong> {respostaAluno}
                          </p>
                          {!estaCorreta && (
                            <p>
                              <strong>Resposta correta:</strong>{" "}
                              {respostaCorreta}
                            </p>
                          )}
                        </div>
                        <div
                          className={`alert ${
                            estaCorreta ? "alert-success" : "alert-danger"
                          }`}
                        >
                          {estaCorreta
                            ? "Resposta correta"
                            : "Resposta incorreta"}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={handleCloseModal}
                >
                  Fechar
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorAvaliacoes;
